const item = $input.first().json;
const b = item.body || item;
const clean = v => (v === undefined || v === null || String(v).trim() === '') ? null : String(v).trim();

const lead = {
  email: clean(b.email || b.Email),
  phone: clean(b.phone || b.mobile || b.telephone),
  full_name: clean(b.name || b.full_name || `${b.first_name || ''} ${b.last_name || ''}`),
  company: clean(b.company || b.business),
  service_requested: clean(b.service || b.service_requested || b.interest),
  message: clean(b.message || b.comments || b.notes),
  budget_range: clean(b.budget || b.budget_range),
  urgency: clean(b.urgency || b.timeline),
  city: clean(b.city),
  state: clean(b.state),
  source: clean(b.source) || 'website_form',
  received_at: new Date().toISOString()
};

if (!lead.email && !lead.phone) {
  throw new Error('Lead needs at least an email or a phone number');
}

const system = `You are a lead qualification AI for a service business.
Score each lead from 0 to 100 using: contact info completeness (20), service intent clarity (25), urgency (20), budget (15), message quality (20).
Score 0-10 for spam or test data (fake emails, "Test User", lottery/inheritance messages).
Respond with valid JSON only, no markdown, in this exact shape:
{"score": <0-100>, "status": "<qualified|needs_followup|unqualified>", "reasoning": "<2-3 sentences>", "key_signals": ["..."], "recommended_action": "<immediate_call|email_followup|nurture_sequence|disqualify>", "missing_info": ["..."]}
Rules: score>=60 qualified, 30-59 needs_followup, <30 unqualified. score>=80 immediate_call, >=60 email_followup, >=30 nurture_sequence, <30 disqualify.`;

const na = v => v || 'Not provided';
const prompt = `Analyze this lead:
EMAIL: ${na(lead.email)}
PHONE: ${na(lead.phone)}
NAME: ${na(lead.full_name)}
COMPANY: ${na(lead.company)}
SERVICE REQUESTED: ${na(lead.service_requested)}
MESSAGE: ${na(lead.message)}
BUDGET: ${na(lead.budget_range)}
URGENCY: ${na(lead.urgency)}
LOCATION: ${na(lead.city)}, ${na(lead.state)}
SOURCE: ${na(lead.source)}`;

return [{ json: { lead, system, prompt } }];

const lead = $('Normalize Lead').first().json.lead;
const response = $input.first().json;
const text = (response.content && response.content[0] && response.content[0].text) || '';

let q = null;
try { q = JSON.parse(text); } catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { q = JSON.parse(m[0]); } catch (e2) {} }
}

if (!q || typeof q.score !== 'number') {
  q = {
    score: 0,
    reasoning: 'Qualification failed - manual review required',
    key_signals: [],
    missing_info: []
  };
  q.parse_failed = true;
}

const score = Math.max(0, Math.min(100, Math.round(q.score)));
const status = q.parse_failed ? 'needs_followup'
  : score >= 60 ? 'qualified' : score >= 30 ? 'needs_followup' : 'unqualified';
const action = q.parse_failed ? 'email_followup'
  : score >= 80 ? 'immediate_call' : score >= 60 ? 'email_followup'
  : score >= 30 ? 'nurture_sequence' : 'disqualify';

return [{ json: {
  success: true,
  lead,
  qualification: {
    score,
    status,
    recommended_action: action,
    reasoning: q.reasoning || '',
    key_signals: Array.isArray(q.key_signals) ? q.key_signals : [],
    missing_info: Array.isArray(q.missing_info) ? q.missing_info : []
  }
} }];
